import json,glob,os,re,collections
files=sorted(glob.glob(os.path.expanduser("~/.claude/projects/*/*.jsonl")),key=os.path.getmtime,reverse=True)[:50]
HEREDOC=re.compile(r"<<-?\s*'?\"?([A-Za-z_][A-Za-z0-9_]*)'?\"?")
def strip_heredocs(cmd):
    out=[];lines=cmd.split("\n");i=0
    while i<len(lines):
        out.append(lines[i]); m=HEREDOC.search(lines[i])
        if m:
            tag=m.group(1); i+=1
            while i<len(lines) and lines[i].strip()!=tag: i+=1
        i+=1
    return "\n".join(out)
want=("npm","npx","entire","gh","wrangler","vitest","tsc","yarn","pnpm","bun","make","cargo","docker","kubectl","tsx")
seg_counter=collections.Counter()
for f in files:
    for line in open(f,errors="replace"):
        try: d=json.loads(line)
        except: continue
        if d.get("type")!="assistant": continue
        c=d.get("message",{}).get("content")
        if not isinstance(c,list): continue
        for b in c:
            if isinstance(b,dict) and b.get("type")=="tool_use" and b.get("name")=="Bash":
                cmd=(b.get("input") or {}).get("command","")
                for seg in re.split(r'\|\||&&|\||;|\n', strip_heredocs(cmd)):
                    s=seg.strip()
                    t=s.split()
                    if t and t[0] in want:
                        seg_counter[" ".join(t[:4])]+=1
for k,v in seg_counter.most_common(45): print(f"{v:4}  {k}")
PY

